// SPDX-License-Identifier: GPL-3.0-only
// Fresh actual C replies generated by test_settings; all other reads use the existing mock. No real MIDI.
import { Device } from "../../app/src/device.js";
import { makeMockDevice, unframe, parse, CMD } from "../../app/src/proto.js";
import { settingsScreen } from "../../app/src/settings.js";
import { bkManifest, bkUnpack, bkR32, bkU32, bkCrc } from "../../fm1backup.js";
const root = document.querySelector("#fixture"), result = document.querySelector("#result");
const check = (ok, message) => { if (!ok) throw Error(message); };
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const until = async (fn, message) => { const end = Date.now() + 10000; while (!fn()) { if (Date.now() >= end) throw Error(message); await new Promise((resolve) => setTimeout(resolve, 10)); } };
const replies = [], screen = settingsScreen(root, { prefResult: (rc) => replies.push(rc), say() {}, confirm: async () => false });
const field = (name) => root.querySelector(`select[aria-label="${name}"]`);
let dev, mock;
try {
  const compare = new URLSearchParams(location.search).get("compare");
  if (compare && !/^[0-9a-f]{40}$/.test(compare)) throw Error("compare needs an exact captured revision");
  const files = compare ? [`${compare}/normal`, "normal", `${compare}/nocpu2`, "nocpu2", "normal"] : ["normal", "nocpu2", "normal"];
  const evidence = [];
  for (const file of files) {
    const response = await fetch(`/build/display-contract/${file}.json`);
    check(response.ok, "fresh native display fixtures required; run the firmware-backed settings suite");
    const data = await response.json(), info = parse[CMD.INFO](unframe(data.info).a);
    mock = makeMockDevice({ auto: false, catalog: true, graph: data.graph, noCpu2: !data.cpu2, uiCaps: info.uiCaps });
    const input = [...mock.access.inputs.values()][0], output = [...mock.access.outputs.values()][0], send = output.send.bind(output);
    const descriptors = data.menu.slice(), ids = descriptors.map((wire) => parse[CMD.MENU_DESC](unframe(wire).a).id), sent = [];
    const adopt = (write) => { const d = parse[CMD.MENU_DESC](unframe(write.descriptor).a); descriptors[d.index] = write.descriptor; return write.reply; };
    output.send = (bytes) => {
      const { cmd, a } = unframe(bytes); let wire; sent.push({ cmd, a });
      if (cmd === CMD.INFO) wire = data.info;
      else if (cmd === CMD.UI_STATE) wire = data.state;
      else if (cmd === CMD.MENU_DESC) wire = descriptors[a[0]];
      else if (cmd === CMD.UI_SET && [4, 5].includes(a[0])) wire = data.invalidPreferences[a[0] - 4];
      else if (cmd === CMD.MENU_SET) {
        const value = (a[1] | a[2] << 7) - 8192;
        if ([1, 2].includes(a[0])) wire = adopt(data.legacyWrites.find((w) => { const r = parse[CMD.MENU_SET](unframe(w.reply).a); return r.id === a[0] && r.value === value; }));
        else if ([3, 4].includes(a[0])) wire = adopt(data.unrelatedWrites.find((w) => unframe(w.reply).a[1] === a[0]));
        else if (a[0] === 34 && data.graph) wire = adopt(data.graphWrites.find((w) => w.requested === value));
        else if (a[0] === 126) wire = data.unknownWrite;
      } else if (cmd === CMD.BACKUP_LIST) wire = data.backupList;
      else if (cmd === CMD.BACKUP_GET && a[0] === 1) wire = data.backupGet.find((w) => bkR32(unframe(w).a, 2) === bkR32(a, 1));
      if (wire) setTimeout(() => input.onmidimessage?.({ data: Uint8Array.from(wire) }), 0); else send(bytes);
    };
    dev = new Device(mock.access); await dev.open();
    dev.on("menu", (items) => screen.menu(items)); dev.on("preferences", () => screen.show(dev)); screen.show(dev);
    const verify = () => {
      check(!!field("LARGE") === !(info.uiCaps & 16), "actual INFO governs LARGE");
      check(!!field("STYLE") === !(info.uiCaps & 32), "actual INFO independently governs STYLE");
      check(!!field("GRAPH") === data.graph, "actual descriptor governs GRAPH presence");
      check(field("ANIM") && field("LEDS"), "unrelated rows stay usable");
      check(same(dev.menu.map((m) => m.id), ids), "actual sparse wire IDs retained");
    };
    verify(); check(dev.preferences.state.caps === info.uiCaps, "actual INFO/UI_STATE caps agree");
    for (const id of [4, 5]) check(await dev.changePreference(id, 1) === 1, "actual producer rejects informational slots");
    for (const id of [1, 2]) for (const value of [0, 1]) check(await dev.menuSet(id, value) === 3, "actual legacy setting remains writable in RAM");
    for (const [id, value] of [[3, 2], [4, 5]]) check(await dev.menuSet(id, value) === 3, "actual unrelated row status retained");
    if (data.graph) {
      check(field("GRAPH").value === "1", "actual initial GRAPH is TURN1");
      for (const value of [0, 1, 2, 3]) {
        const before = replies.length, control = field("GRAPH"); control.value = String(value);
        control.dispatchEvent(new Event("input")); control.dispatchEvent(new Event("change"));
        await until(() => replies.length > before && dev.menu.find((m) => m.id === 34).value === value, "actual GRAPH control applies captured reply");
        check(replies.at(-1) === 3, "RAM-only reply remains applied"); verify();
      }
      await dev.menuSet(34, 99); await dev.menuSet(34, -1);
      check(dev.menu.find((m) => m.id === 34).value === 0, "actual producer clamps GRAPH logical value");
    }
    await dev.readMenu(); await dev.syncPreferences(true); screen.show(dev); verify();
    check(dev.menu.find((m) => m.id === 1).value === 1 && dev.menu.find((m) => m.id === 2).value === 1, "actual hidden values survive refresh");
    check(await dev.menuSet(126, 1) === 1, "actual unknown-id echo remains refused"); verify();
    const list = bkManifest(await dev.rq([CMD.BACKUP_LIST, []])), record = list.find((x) => x.id === 1), bytes = new Uint8Array(record.size);
    for (let off = 0; off < bytes.length; off += 256) {
      const count = Math.min(256, bytes.length - off), a = await dev.rq([CMD.BACKUP_GET, [1, ...bkU32(off), count & 127, count >> 7]]);
      check(a[0] === 1 && a[1] === 0 && bkR32(a, 2) === off, "actual backup chunk address/status"); bytes.set(bkUnpack(a.slice(9), count), off);
    }
    check(same([...bytes], data.backup) && bkCrc(bytes) === record.crc, "actual backup wire retains opaque settings bytes");
    check(same(data.backup, data.roundtrip), "producer C imports/exports exact original bytes");
    evidence.push({ revision: data.revision, cpu2: data.cpu2, caps: info.uiCaps, graph: data.graph, menu: ids.length, backupBytes: bytes.length, sets: sent.filter((r) => r.cmd === CMD.MENU_SET).map((r) => r.a[0]) });
    dev.close(); mock.stop(); screen.show(null);
  }
  window.evidence = evidence;
  result.textContent = "PASS: fresh C INFO/UI_STATE/MENU/settings/GRAPH/backup replay, actual control writes, CPU2 sparse IDs, refresh and retained legacy bytes";
} catch (error) { result.textContent = "FAIL: " + error.message; throw error; }
finally { dev?.close(); mock?.stop(); }
